    'mcp_title' => 'Agents IA (MCP)',
    'mcp_note' => 'Connectez Claude Code, Codex, ChatGPT et d\'autres agents IA à votre CRM.',
    'mcp_why' => '<strong>Pourquoi :</strong> MCP permet aux agents IA de lire et gérer vos tâches, projets, clients et chats via un protocole unique — avec les mêmes règles d\'accès que l\'interface web.',
    'mcp_intro' => 'TropaTT inclut un serveur MCP intégré (Model Context Protocol) — le même protocole compris par Claude Code, Codex, ChatGPT et d\'autres agents IA compatibles.',
