    'usage_step4' => '<strong>Coordination</strong> — via chat, commentaires, @mentions, notifications.',
    'usage_step5' => '<strong>Exécution</strong> — listes de tâches, Kanban, Mon Jour, Ma Semaine.',
    'usage_step6' => '<strong>Suivi</strong> — Gantt, tableaux de bord, analytique, charge, signaux de risque.',
    'usage_step7' => '<strong>Automatisation</strong> — règles de workflow, SLA, webhooks, chaînes d\'approbation.',
    'usage_examples_heading' => 'Exemples concrets',
